def hex_fill(hex_color):
    return PatternFill("solid", fgColor=hex_color)

def font(bold=False, size=10, color="000000", italic=False, name="Arial"):
    return Font(bold=bold, size=size, color=color, italic=italic, name=name)

def align(h="left", v="center", wrap=True):
    return Alignment(horizontal=h, vertical=v, wrap_text=wrap)

def border(color="CCCCCC"):
    s = Side(style="thin", color=color)
    return Border(left=s, right=s, top=s, bottom=s)

def thick_border(color=NAVY):
    s = Side(style="medium", color=color)
    thin = Side(style="thin", color="CCCCCC")
    return Border(left=s, right=s, top=s, bottom=s)

def set_cell(ws, row, col, value, 
             bold=False, size=10, fg=WHITE, font_color="000000",
             h_align="left", wrap=True, italic=False, border_color="CCCCCC",
             number_format=None):
    c = ws.cell(row=row, column=col, value=value)
    c.font = Font(bold=bold, size=size, color=font_color, italic=italic, name="Arial")
    c.fill = hex_fill(fg)
    c.alignment = Alignment(horizontal=h_align, vertical="center", wrap_text=wrap)
    c.border = border(border_color)
    if number_format:
        c.number_format = number_format
    return c

