row4 = 4
for dp in deepseek_prompts:
    ws4.row_dimensions[row4].height = 200
    tid, name, ptype, prompt = dp
    bg = GRAY1 if row4 % 2 == 0 else WHITE
    
    for i, v in enumerate([tid, name, ptype, prompt]):
        col = 2 + i
        c = ws4.cell(row4, col, v)
        c.font = Font(bold=(i==0), size=9 if i < 3 else 8,
                      color=NAVY if i==0 else (TEAL if i==2 else "111827"),
                      name="Arial")
        c.fill = hex_fill(LTGOLD if i==0 else (TEAL_LT if i==2 else bg))
        c.alignment = Alignment(horizontal="center" if i in [0,2] else "left",
                                vertical="top", wrap_text=True)
        c.border = border()
    row4 += 1

